import React, { useState } from 'react';
import { Routes, Route, useLocation, useNavigate } from 'react-router-dom';
import Sidebar from '../Dashboard/Layout/Sidebar';
import TopBar from '../Dashboard/Layout/TopBar';
import MobileMenu from '../Dashboard/Layout/MobileMenu';
import DashboardHome from '../Dashboard/Pages/DashboardHome';
import UsersPage from '../Dashboard/Pages/UsersPage';
import ProductsPage from '../Dashboard/Pages/ProductsPage';
import OrdersPage from '../Dashboard/Pages/OrdersPage';
import AnalyticsPage from '../Dashboard/Pages/AnalyticsPage';
import MessagesPage from '../Dashboard/Pages/MessagesPage';
import SettingsPage from '../Dashboard/Pages/SettingsPage';

const Dashboard = ({ onLogout }) => {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [notifications] = useState([
    { id: 1, title: 'New order received', message: 'Order #1234 from John Doe', time: '5 min ago', unread: true },
    { id: 2, title: 'Payment processed', message: 'Payment of $450 completed', time: '1 hour ago', unread: true },
    { id: 3, title: 'New user registered', message: 'Sarah Johnson joined the platform', time: '2 hours ago', unread: false },
  ]);

  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = () => {
    if (onLogout) {
      onLogout();
    }
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-neutral-50 to-primary-50 dark:from-neutral-950 dark:to-primary-950">
      <Sidebar 
        sidebarOpen={sidebarOpen}
        location={location}
        onLogout={handleLogout}
      />

      <div className={`lg:pl-64 transition-all duration-300`}>
        <TopBar 
          mobileMenuOpen={mobileMenuOpen}
          setMobileMenuOpen={setMobileMenuOpen}
          location={location}
          notifications={notifications}
        />

        <main className="p-6">
          <Routes>
            <Route path="/" element={<DashboardHome />} />
            <Route path="/users" element={<UsersPage />} />
            <Route path="/products" element={<ProductsPage />} />
            <Route path="/orders" element={<OrdersPage />} />
            <Route path="/analytics" element={<AnalyticsPage />} />
            <Route path="/messages" element={<MessagesPage />} />
            <Route path="/settings" element={<SettingsPage />} />
          </Routes>
        </main>
      </div>

      <MobileMenu 
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
      />
    </div>
  );
};

export default Dashboard;
